local r=fu:GetResolve();local p=r:GetProjectManager():GetCurrentProject();print('PROJECT',p:GetName());print('RENDERING',p:IsRenderingInProgress());for i=1,p:GetTimelineCount() do local t=p:GetTimelineByIndex(i);if string.find(t:GetName(),'v24') then print('V24_TIMELINE',t:GetName(),t:GetEndFrame(),#t:GetItemListInTrack('audio',1)) end end;for _,j in ipairs(p:GetRenderJobList()) do if string.find(j.OutputFilename or '', 'clean') then dump(j) end end